pub struct Solution;

impl Solution {
    pub fn search_range(nums: Vec<i32>, target: i32) -> Vec<i32> {
        let first = nums.partition_point(|&x| x < target);
        if first == nums.len() || nums[first] != target {
            return vec![-1, -1];
        }
        let last = nums.partition_point(|&x| x <= target) - 1;
        vec![first as i32, last as i32]
    }
}

